                                                <span className="text-[10px] font-mono font-bold text-zinc-300">
                                                    Est. Cost: ~${((payNum * (route.impact / 100)) + route.fee + route.gas + (payNum * 0.0005)).toLocaleString('en-US', { maximumFractionDigits: 0 })}
                                                </span>
                                            </div>
