    // A. Apply Accounting Method Logic (Simulated Multipliers against FIFO base)
    // FIFO = Base (Standard)
    // LIFO = Usually higher cost basis, so lower PnL (e.g. 85% of FIFO)
    // HIFO = Highest cost basis, so lowest PnL (e.g. 72% of FIFO)

    let effectivePnL = baseRealizedPnL;
