                              {tx.pnl > 0 ? '+' : ''}{tx.pnl === 0 ? '--' : `$${tx.pnl.toLocaleString('en-US', { minimumFractionDigits: 2 })}`}
                           </span>
                        </td>
                        <td className="py-4 text-right pr-4">
                           {tx.status === 'NEEDS_REVIEW' ? (
