           <p className="text-zinc-400 text-xs font-medium mt-1">
              Real-time tax liability tracking, audit-ready reports, and portfolio reconciliation.
           </p>
        </div>

        {/* STANDARDIZED CONTROL BAR */}
        <div className="flex flex-wrap items-center gap-3 bg-[#0a0a0a] p-2 rounded-xl border border-white/5 shadow-inner">

           {/* 1. Fiscal Year */}
           <div className="relative group">
              <div className="absolute inset-y-0 left-3 flex items-center pointer-events-none">
                <Calendar size={12} className="text-zinc-500" />
              </div>
              <select 
                value={fiscalYear}
                onChange={(e) => setFiscalYear(e.target.value)}
                className="appearance-none bg-zinc-900 border border-white/10 rounded-lg py-2 pl-9 pr-8 text-[10px] font-bold text-white outline-none focus:border-emerald-500 transition-colors uppercase tracking-wider hover:bg-zinc-800 cursor-pointer h-9"
              >
                 <option value="2024">FY 2024</option>
                 <option value="2023">FY 2023</option>
              </select>
              <ChevronDown size={12} className="absolute right-3 top-1/2 -translate-y-1/2 text-zinc-500 pointer-events-none" />
           </div>

           <div className="w-px h-5 bg-white/10 mx-1"></div>

           {/* 2. Jurisdiction */}
           <div className="relative group">
              <div className="absolute inset-y-0 left-3 flex items-center pointer-events-none">
                <Globe size={12} className="text-blue-500" />
              </div>
              <select 
                value={jurisdiction}
                onChange={handleJurisdictionChange}
                className="appearance-none bg-zinc-900 border border-white/10 rounded-lg py-2 pl-9 pr-8 text-[10px] font-bold text-white outline-none focus:border-blue-500 transition-colors uppercase tracking-wider hover:bg-zinc-800 cursor-pointer min-w-[140px] h-9"
              >
                 <option value="USA">USA (IRS)</option>
                 <option value="UK">UK (HMRC)</option>
                 <option value="Germany">Germany (BZSt)</option>
                 <option value="Dubai">Dubai (0% Tax)</option>
                 <option value="Custom">Custom Region</option>
              </select>
              <ChevronDown size={12} className="absolute right-3 top-1/2 -translate-y-1/2 text-zinc-500 pointer-events-none" />
           </div>

           {/* 3. Tax Rate Input (Dynamic) */}
           <div className="relative flex items-center">
              <div className="absolute inset-y-0 left-3 flex items-center pointer-events-none">
                <Settings size={12} className="text-zinc-500" />
              </div>
              <input 
                 type="number" 
                 value={taxRate}
                 onChange={(e) => setTaxRate(Number(e.target.value))}
                 className="w-20 bg-zinc-900 border border-white/10 rounded-lg py-2 pl-9 pr-2 text-[10px] font-bold text-white outline-none focus:border-emerald-500 transition-colors text-center h-9"
              />
              <span className="absolute right-3 text-[10px] font-bold text-zinc-600">%</span>
           </div>

           <div className="w-px h-5 bg-white/10 mx-1"></div>

           {/* 4. Accounting Method */}
           <div className="relative">
              <div className="absolute inset-y-0 left-3 flex items-center pointer-events-none">
                <Calculator size={12} className="text-purple-500" />
              </div>
              <select 
                value={accountingMethod}
                onChange={(e) => setAccountingMethod(e.target.value as any)}
