      <div className="flex items-center justify-between mb-8 shrink-0">
        <div className="flex p-1 bg-black/40 rounded-2xl border border-white/5 relative">
          <button 
            onClick={() => setTradeMode('market')}
            className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${
                tradeMode === 'market' 
                ? 'bg-emerald-500 text-black shadow-[0_0_20px_rgba(16,185,129,0.2)] border border-emerald-400/20' 
                : 'text-zinc-500 hover:text-zinc-300 hover:bg-zinc-800/50 border border-transparent'
            }`}
          >
            Swap
          </button>

          <button 
            onClick={() => setTradeMode('limit')}
            className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${
                tradeMode === 'limit' 
                ? 'bg-emerald-500 text-black shadow-[0_0_20px_rgba(16,185,129,0.2)] border border-emerald-400/20' 
                : 'text-zinc-500 hover:text-zinc-300 hover:bg-zinc-800/50 border border-transparent'
            }`}
          >
            Limit
          </button>

          {/* ALGO TAB */}
          <button 
            onClick={() => setTradeMode('algo')}
            className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all flex items-center gap-2 relative ${
                tradeMode === 'algo' 
                ? 'bg-emerald-500 text-black shadow-[0_0_20px_rgba(16,185,129,0.2)] border border-emerald-400/20' 
                : 'text-zinc-500 hover:text-zinc-300 hover:bg-zinc-800/50 border border-transparent'
            }`}
          >
            <Ghost size={12} /> 
            <span>Algo</span>
          </button>
        </div>

        {/* SETTINGS */}
        <div className="flex items-center gap-6">
            <button 
                onClick={openSettingsModal}
                className="bg-zinc-800 p-2.5 rounded-xl border border-white/5 text-gray-500 hover:text-white cursor-pointer transition-colors outline-none hover:bg-zinc-700"
            >
                <Settings size={18} aria-hidden="true" />
            </button>
        </div>
      </div>

      {/* VIEW CONTENT */}
      <div className="flex-1 h-full">
        {tradeMode === 'market' && (
           <div className="h-full max-w-2xl mx-auto">
             <QuickSwap />
           </div>
        )}
        {tradeMode === 'limit' && (
           <div className="h-full flex flex-col items-center justify-center text-zinc-500 space-y-4 border border-white/5 rounded-3xl bg-zinc-900/20">
              <p className="text-sm font-black uppercase tracking-widest">Limit Order Interface</p>
              <p className="text-xs">Select "Trading Terminal" for advanced order types.</p>
           </div>
        )}
        {tradeMode === 'algo' && (
           <div className="h-full flex flex-col items-center justify-center text-zinc-500 space-y-4 border border-white/5 rounded-3xl bg-zinc-900/20">
              <Ghost size={48} className="opacity-20" />
              <p className="text-sm font-black uppercase tracking-widest">Algorithmic Execution</p>
              <p className="text-xs">TWAP / VWAP / ICEBERG available in Pro mode.</p>
           </div>
        )}
      </div>
    </div>
  );
};

export default ExecutionView;
